#!/usr/bin/env node
// Builds apps/web/public/examples/index.json and a poster for each example generated by scripts/website-examples.py.
// Order follows apps/web/src/examples.ts. Media links point at the static files; API-only links are dropped.
import fs from 'node:fs';
import path from 'node:path';
import {execFileSync} from 'node:child_process';
import {fileURLToPath} from 'node:url';

const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
const dir=path.join(root,'apps/web/public/examples'),jobs=path.join(root,'examples/website-jobs');
const order=[...fs.readFileSync(path.join(root,'apps/web/src/examples.ts'),'utf8').matchAll(/slug:'([a-z0-9-]+)'/g)].map(m=>m[1]);
// Where in the video the poster frame is taken: late enough that interface formats show a filled board.
const posterAt={skit:.22,sketch:.8,prreview:.45,tierlist:.95,groupchat:.7};

const entries=[];
for(const slug of order){
  // Job records keep API-only links, so they live outside the website: examples/website-jobs/<slug>.json
  const folder=path.join(dir,slug),fresh=path.join(folder,'job.json'),jobFile=path.join(jobs,`${slug}.json`);
  if(fs.existsSync(fresh)){fs.mkdirSync(jobs,{recursive:true});fs.renameSync(fresh,jobFile);}
  if(!fs.existsSync(jobFile)){console.error(`${slug}: not generated yet, skipped`);continue;}
  const job=JSON.parse(fs.readFileSync(jobFile,'utf8'));
  const seconds=Number(job.durationSeconds)||Number(execFileSync('ffprobe',['-v','error','-show_entries','format=duration','-of','csv=p=0',path.join(folder,'video.mp4')],{encoding:'utf8'}));
  execFileSync('ffmpeg',['-y','-loglevel','error','-ss',String(Math.max(1,seconds*(posterAt[job.format]??.5))),'-i',path.join(folder,'video.mp4'),'-frames:v','1','-vf','scale=540:960',path.join(folder,'poster.png')]);
  const {outputs,audioUrl,downloadUrl,videoUrl,posterUrl,mediaExpiresAt,...rest}=job;
  entries.push({...rest,videoUrl:`/examples/${slug}/video.mp4`,downloadUrl:`/examples/${slug}/video.mp4`,posterUrl:`/examples/${slug}/poster.png`,audioUrl:null});
  console.log(`${slug}: ${job.format} ${job.language} ${Math.round(seconds)}s`);
}
const text=JSON.stringify(entries,null,2);
if(text.includes('/Users/')||text.includes('/api/v1/'))throw new Error('Private paths or API links would be published.');
fs.writeFileSync(path.join(dir,'index.json'),text+'\n');
console.log(`index.json: ${entries.length} examples`);
